//! Deterministic SPIR-V compute shader modules for all 6 [`KernelSlot`]s,
//! compiled from `crates/qsag-accel/shaders/*.comp` with `--target-env vulkan1.2`.

use crate::{CertifiedKernelPin, KernelSlot, KernelTargetArch};

const fn words_to_le_bytes<const W: usize, const B: usize>(words: &[u32; W]) -> [u8; B] {
    assert!(B == W * 4);
    let mut out = [0u8; B];
    let mut i = 0usize;
    while i < W {
        let le = words[i].to_le_bytes();
        let base = i * 4;
        out[base] = le[0];
        out[base + 1] = le[1];
        out[base + 2] = le[2];
        out[base + 3] = le[3];
        i += 1;
    }
    out
}

